async def seed_default_settings(session) -> int:
    """Idempotent global seed. Returns rows attempted."""
    from sqlalchemy import text as _text
    n = 0
    for r in DEFAULT_SETTINGS:
        try:
            await session.execute(
                _text("""
                    INSERT INTO default_settings
                    (default_setting_uuid, default_setting_category, default_setting_subcategory,
                     default_setting_name, default_setting_value, default_setting_enabled, default_setting_description)
                    VALUES (:u, :c, :s, :n, :v, :e, :d)
                    ON CONFLICT (default_setting_uuid) DO NOTHING
                """),
                {"u": r["uuid"], "c": r["category"], "s": r["subcategory"], "n": r["name"], "v": r["value"], "e": r["enabled"], "d": r["description"]},
            )
        except Exception:
            try:
                await session.execute(
                    _text("""
                        INSERT OR IGNORE INTO default_settings
                        (default_setting_uuid, default_setting_category, default_setting_subcategory,
                         default_setting_name, default_setting_value, default_setting_enabled, default_setting_description)
                        VALUES (:u, :c, :s, :n, :v, :e, :d)
                    """),
                    {"u": r["uuid"], "c": r["category"], "s": r["subcategory"], "n": r["name"], "v": r["value"], "e": r["enabled"], "d": r["description"]},
                )
            except Exception:
                continue
        n += 1
    try:
        await session.commit()
    except Exception:
        pass
    return n
